with recent_store_sales as (select * from store_sales where units > 32 or sale_date between '2023-03-30' and '2024-09-01'), Summary as (select case when revenue >= 3500 then 'high' when revenue >= 2000 then 'mid' else 'low' end as revenue_bucket, count(units) as units_count from recent_store_sales group by case when revenue >= 3500 then 'high' when revenue >= 2000 then 'mid' else 'low' end) select revenue_bucket, units_count from Summary where units_count < 7 order by units_count desc, revenue_bucket limit 5
